package com.habilitesrandom.api;
import net.minecraft.resources.Identifier;import java.util.*;
public final class TransformationBuilder {private final Identifier id;private String name="",description="",particle="",sound="";private int duration,cooldown=20;private double damage=1,speed=1,defense=1;private List<EffectSpec> effects=List.of();TransformationBuilder(Identifier id){this.id=Objects.requireNonNull(id);}public TransformationBuilder displayName(String v){name=v;return this;}public TransformationBuilder description(String v){description=v;return this;}public TransformationBuilder durationTicks(int v){duration=v;return this;}public TransformationBuilder cooldownTicks(int v){cooldown=v;return this;}public TransformationBuilder modifiers(double d,double s,double f){damage=d;speed=s;defense=f;return this;}public TransformationBuilder effects(EffectSpec...v){effects=List.of(v);return this;}public TransformationBuilder presentation(String p,String s){particle=p;sound=s;return this;}public TransformationDefinition build(){return new TransformationDefinition(id,name,description,duration,cooldown,damage,speed,defense,effects,particle,sound);}}
